import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"选哪种安装方式","description":"Linux 可先用一键脚本装 PostgreSQL；Windows 只走手动安装。官方二进制已内嵌管理台。","frontmatter":{"title":"选哪种安装方式","description":"Linux 可先用一键脚本装 PostgreSQL；Windows 只走手动安装。官方二进制已内嵌管理台。"},"headers":[],"relativePath":"guide/install/index.md","filePath":"guide/install/index.md","lastUpdated":1790057721000}`),a={name:`guide/install/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="选哪种安装方式" tabindex="-1">选哪种安装方式 <a class="header-anchor" href="#选哪种安装方式" aria-label="Permalink to “选哪种安装方式”">​</a></h1><p>KiriVers 的主安装路径是 <strong>GitHub Releases 可执行文件</strong> 或 Docker 镜像 <code>kirizuofficial/kirivers</code>。不必安装 Node.js 或 Go，也不必编译或拷贝管理台网页。官方可执行文件已内嵌管理 UI。</p><p>以当前 <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 与 Docker Hub 标签为准，不要使用会 404 的猜测下载链接。</p><h2 id="对照表" tabindex="-1">对照表 <a class="header-anchor" href="#对照表" aria-label="Permalink to “对照表”">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>建议</th></tr></thead><tbody><tr><td>Linux（Debian/Ubuntu：apt；RHEL/CentOS/Fedora：yum 或 dnf）</td><td>可先跑 <a href="/guide/install/one-click">一键脚本</a> 装 PostgreSQL（可选 Redis），再按 <a href="/guide/install/manual">手动安装</a> 下载程序</td></tr><tr><td>Windows</td><td><strong>不要</strong>跑一键脚本。按手动安装：官方安装包装 PostgreSQL，可选 Redis 或使用内存缓存，再下载 <code>.exe</code></td></tr><tr><td>macOS 及其他没有 apt/yum/dnf 的 Linux</td><td>一键脚本会退出。按手动安装，或使用 <a href="/guide/install/docker">Docker</a></td></tr><tr><td>已有 Docker</td><td><a href="/guide/install/docker">Docker</a> 或 <a href="/guide/install/compose">Compose</a> 把程序与数据库一起跑起来</td></tr></tbody></table><h2 id="releases-files" tabindex="-1">如何选 Releases 文件 <a class="header-anchor" href="#releases-files" aria-label="Permalink to “如何选 Releases 文件”">​</a></h2><p>打开 <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers/releases</a>，按<strong>前缀</strong>挑包：<code>KiriVers-&lt;系统&gt;-&lt;架构&gt;-&lt;哈希&gt;.zip</code>。末尾六位数是包内二进制的 SHA-256 前缀，所以文件名每次发版都会变——认准前缀，不要收藏具体链接。解压后里面的可执行文件叫 <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code>（Windows 为 <code>.exe</code>）。</p><table tabindex="0"><thead><tr><th>你的系统</th><th>常见 CPU</th><th>下载前缀</th></tr></thead><tbody><tr><td>Windows</td><td>x64</td><td><code>KiriVers-Windows-x86_64-</code></td></tr><tr><td>Windows</td><td>32 位 x86</td><td><code>KiriVers-Windows-x86-</code></td></tr><tr><td>Windows</td><td>Arm</td><td><code>KiriVers-Windows-arm64-</code></td></tr><tr><td>Linux</td><td>x86_64</td><td><code>KiriVers-Linux-x86_64-</code></td></tr><tr><td>Linux</td><td>aarch64</td><td><code>KiriVers-Linux-arm64-</code></td></tr><tr><td>Linux</td><td>32 位 x86</td><td><code>KiriVers-Linux-x86-</code></td></tr><tr><td>Linux</td><td>ARMv7（树莓派 2/3 等）</td><td><code>KiriVers-Linux-armv7-</code></td></tr><tr><td>Linux</td><td>RISC-V 64</td><td><code>KiriVers-Linux-riscv64-</code></td></tr><tr><td>macOS</td><td>Intel</td><td><code>KiriVers-macOS-x86_64-</code></td></tr><tr><td>macOS</td><td>Apple Silicon</td><td><code>KiriVers-macOS-arm64-</code></td></tr></tbody></table><p>另附 <code>SHA256SUMS.txt</code>（可直接 <code>sha256sum -c</code> 校验下载件）与 <code>frontend-dist.zip</code>（管理台静态文件，官方二进制已内嵌，通常不需要）。</p><p>在 Windows 任务管理器「性能」或「系统信息」中查看是 x64 还是 ARM。在 Linux / macOS 上运行 <code>uname -m</code>（<code>x86_64</code> 或 <code>aarch64</code> / <code>arm64</code>）。</p><div class="warning custom-block"><p class="custom-block-title">三种 Linux 包的 libc 差别</p><p><code>x86_64</code> 与 <code>arm64</code> 是 <strong>musl</strong> 构建（能跑在 Alpine 上）；<code>x86</code>、<code>armv7</code>、<code>riscv64</code> 是 <strong>glibc 交叉构建</strong>，要求目标机 glibc ≥ 2.39（Ubuntu 24.04 一代），armv7 还需 hard-float，riscv64 需 RVA20+ 用户态。老系统请用 <a href="/guide/install/docker">Docker</a>（仅 amd64/arm64）或自编译。</p></div><p>下一步：<a href="/guide/install/one-click">一键安装</a>（仅 Linux 依赖）或 <a href="/guide/install/manual">手动安装</a>。</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};